extension Fuzz {
private func computeLines(text: SyntaxText) -> SourceLineTable {
  var lineEnds: [AbsolutePosition]
= []
  let endPos = text.forEachEndOfLine(position: .startOfFile)
{ pos in
    lineEnds.append
(pos)
  }
  precondition(endPos.utf8Offset == text.count)
  return SourceLineTable(lineEnds: lineEnds, virtualFiles: [], endOfFile: endPos)
}
}

